pub fn fmt_msg(msg: &mut String) -> String {
    // Extract the first 5 bytes as an owned String `tag`
    let tag = msg.drain(..5).collect::<String>();

    // Compute the priority based on the tag
    let prio = tag.starts_with("HIGH");

    // Return the formatted string
    format!("{prio}: {msg}")
}
